"5","bottom":"5","left":"5","isLinked":true}},"elements":[],"widgetType":"image"},{"id":"e76e96b","elType":"widget","settings":{"editor":"<p>"Joining Cigala Cycling and working with Matteo took the T out of tedious and put back the M for Motivation. I no longer have the mental stress of racking up hours and hours of junk miles or the stress of creating a program where I constantly think "will or won't it work".<br />I have gained hugely this season in power and fitness and matteos help getting me from 95kg down to 79kg was a massive factor. I trust Matteo to keep me physically fit, healthy and keep my relationships in tact with the flexibility and time management he provides me.<br />Every session is different, exciting and more importantly, enjoyable. Its a motto I live by now....Train Smarter, Ride Faster"</p>","align":"center","typography_typography":"custom","typography_font_family":"Raleway","typography_font_size":{"unit":"px","size":19,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":15,"sizes":[]},"typography_font_weight":"500","text_color":"#161616","_element_width":"initial","_element_custom_width":{"unit":"%","size":73,"sizes":[]},"_element_custom_width_mobile":{"unit":"%","size":100,"sizes":[]},"_flex_align_self":"center"},"elements":[],"widgetType":"text-editor"},{"id":"07e0537","elType":"widget","settings":{"width":{"unit":"%","size":27,"sizes":[]},"width_mobile":{"unit":"%","size":36,"sizes":[]},"align":"center","text":"Divider","color":"#7A7A7A","gap_mobile":{"unit":"px","size":2,"sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"9328dd3","elType":"widget","settings":{"editor":"<p>Barry Fitzgerald, Newcastle West</p>","align":"center","typography_typography":"custom","typography_font_family":"Raleway","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"500","paragraph_spacing_mobile":{"unit":"px","size":0,"sizes":[]},"text_color":"#7A7A7A","_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":